fn fib() -> impl Iterator<Item = u64> {
    std::iter::successors(Some((0u64, 1u64)), |&(a, b)| Some((b, a + b)))
        .map(|(a, _)| a)
}

for n in fib().filter(|n| n % 2 == 0).take(10) {
    println!("{n}");                       // pulled lazily, then dropped
}

